contract InvMutTest {
    C c;
    bool called;
    address lastFrom;
    address lastTo;
    uint lastV;

    constructor(C _c) { c = _c; }

    fallback() external payable {
        bytes4 sel = bytes4(keccak256("transferFrom(address,address,uint256)"));
        if (msg.data.length >= 100 && bytes4(msg.data) == sel) {
            (address f, address t, uint v) = abi.decode(msg.data[4:], (address, address, uint256));
            called = true;
            lastFrom = f;
            lastTo = t;
            lastV = v;
        }
    }

    function run(address from, address[] memory tos, uint v) public {
        require(tos.length == 1);
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok && called && lastFrom == from && lastTo == tos[0] && lastV == v);
    }

    receive() external payable {}
}

